    director_inherit_help={en="Common horde/trickle members follow their HCM size setting; elites follow Elite members per group. Specialists follow slot capacity; monsters follow encounter count. Patrol ordinary members stay at 1×. Custom waves remain explicit.",["zh-cn"]="普通尸潮／小股成员跟随各自的 HCM 人数倍率，精英跟随敌群精英人数。特感跟随并行容量，怪物跟随遭遇数；巡逻普通成员保持 1×。自定义波数始终由本规则指定。",["zh-tw"]="普通屍潮／小股成員跟隨各自的 HCM 人數倍率，精英跟隨敵群精英人數。特感跟隨並行容量，怪物跟隨遭遇數；巡邏普通成員保持 1×。自定義波數始終由本規則指定。"},
    director_frequency_help={en="Horde, trickle and specialist rules follow the matching HCM frequency. Other categories start at 1×. Higher frequency shortens later time or distance intervals; first-arrival and cooldown values stay explicit.",["zh-cn"]="尸潮、小股潮、特感分别跟随对应的 HCM 频率，其他类别从 1× 开始。频率越高，再次投放的时间或距离间隔越短；首次时间与冷却仍使用本规则的明确值。",["zh-tw"]="屍潮、小股潮、特感分別跟隨對應的 HCM 頻率，其他類別從 1× 開始。頻率越高，再次投放的時間或距離間隔越短；首次時間與冷卻仍使用本規則的明確值。"},
    director_budget_help={en="Each HED encounter is bounded to 256 ordinary troops, 16 specialists or 3 monsters across all waves. Native specialist slots and available locations may further limit arrivals.",["zh-cn"]="每次 HED 遭遇的所有波次合计最多 256 名普通敌人、16 名特感或 3 只怪物。原版特感槽位及出生位置仍可能进一步限制到场。",["zh-tw"]="每次 HED 遭遇的所有波次合計最多 256 名普通敵人、16 名特感或 3 只怪物。原版特感槽位及出生位置仍可能進一步限制到場。"},
    director_changed={en="Edited values",["zh-cn"]="已修改的设置",["zh-tw"]="已修改的設定"},
    director_no_changes={en="No native overrides yet. HCM values are inherited.",["zh-cn"]="尚未覆盖原版字段，当前跟随 HCM。",["zh-tw"]="尚未覆蓋原版欄位，當前跟隨 HCM。"},
    director_value_mode={en="How this value is applied",["zh-cn"]="此值的应用方式",["zh-tw"]="此值的應用方式"},
    director_follow={en="Follow HCM",["zh-cn"]="跟随 HCM",["zh-tw"]="跟隨 HCM"},
    director_fixed={en="Use a fixed value",["zh-cn"]="使用固定值",["zh-tw"]="使用固定值"},
    director_relative={en="Multiply the HCM value",["zh-cn"]="在 HCM 结果上乘倍率",["zh-tw"]="在 HCM 結果上乘倍率"},
    director_original={en="Original: %s",["zh-cn"]="原版：%s",["zh-tw"]="原版：%s"},
    director_coarse_value={en="After HCM: %s",["zh-cn"]="HCM 后：%s",["zh-tw"]="HCM 後：%s"},
    director_effective={en="HED template result: %s",["zh-cn"]="HED 模板结果：%s",["zh-tw"]="HED 模板結果：%s"},
    director_factor={en="Additional value multiplier",["zh-cn"]="额外数值倍率",["zh-tw"]="額外數值倍率"},
    director_relative_help={en="HCM is applied first, then this multiplier. The field's valid range and integer rounding still apply. Other native mission modifiers may apply afterward.",["zh-cn"]="先计算 HCM，再乘此倍率；仍受字段有效范围和整数取整约束。之后可能继续叠加原版任务修正。",["zh-tw"]="先計算 HCM，再乘此倍率；仍受欄位有效範圍和整數取整約束。之後可能繼續疊加原版任務修正。"},
    director_template_help={en="Choose the source family, then its mode and difficulty branch. Native identifiers are available in details; the numbers here are template values, not guaranteed on-screen counts.",["zh-cn"]="先选刷怪来源，再选模式与难度分支。此处编辑模板数值，不代表保证同屏人数；原版标识可在详情中查看。",["zh-tw"]="先選刷怪來源，再選模式與難度分支。此處編輯模板數值，不代表保證同屏人數；原版標識可在詳情中檢視。"},
    director_resistance={en="Resistance branch %s",["zh-cn"]="抗性档 %s",["zh-tw"]="抗性檔 %s"},
    director_challenge={en="Challenge branch %s",["zh-cn"]="挑战档 %s",["zh-tw"]="挑戰檔 %s"},
